@@ -1,7 +1,49 @@
 package endpoint

-import "net/url"
+import (
+	"errors"
+	"net"
+	"net/url"
+	"strings"
+)

 func Validate(raw string, allowedHosts []string) (*url.URL, error) {
-	return url.Parse(raw)
+	u, err := url.Parse(raw)
+	if err != nil {
+		return nil, err
+	}
+
+	if u.Scheme != "https" {
+		return nil, errors.New("endpoint: scheme must be https")
+	}
+
+	if u.User != nil {
+		return nil, errors.New("endpoint: userinfo not allowed")
+	}
+
+	host := u.Hostname()
+	if host == "" {
+		return nil, errors.New("endpoint: empty hostname")
+	}
+
+	if net.ParseIP(host) != nil {
+		return nil, errors.New("endpoint: IP-literal hosts not allowed")
+	}
+
+	if len(allowedHosts) == 0 {
+		return nil, errors.New("endpoint: allowedHosts must be nonempty")
+	}
+
+	allowed := false
+	for _, h := range allowedHosts {
+		if strings.EqualFold(host, h) {
+			allowed = true
+			break
+		}
+	}
+	if !allowed {
+		return nil, errors.New("endpoint: host not in allowlist")
+	}
+
+	return u, nil
 }
